effect.shader:
        // Chromatic Displacement Search
        // Single-pass RGB displacement with soft-edged scanning beam

        void main() {
            vec2 uv = acScreenNorm;

            // Beam mask (horizontal band by default)
            vec2 d = uv - beamCenter;
            float halfW = beamWidth * 0.5;
            float mask = smoothstep(halfW + beamFeather, halfW - beamFeather, abs(d.x));
            float weight = mask * beamIntensity;

            // Displacement vector
            vec2 offset = vec2(cos(angle), sin(angle)) * dispDist * weight;

            // Sample shifted channels
            vec4 colR = texture2DCv(inputImg.texture, uv + offset);
            vec4 colG = texture2DCv(inputImg.texture, uv);
            vec4 colB = texture2DCv(inputImg.texture, uv - offset);

            // Assemble RGB from displaced samples
            vec4 displaced = vec4(colR.r, colG.g, colB.b, colG.a);

            // Original sample
            vec4 original = texture2DCv(inputImg.texture, uv);

            // Blend original and displaced inside the beam
            gl_FragColor = mix(original, displaced, weight);
        }
